```jac
"""Return locations of the input connected to an output position."""
def conv_connected_inputs(
    input_shape: tuple[int, ...],
    kernel_shape: tuple[int, ...],
    output_position: tuple[int, ...],
    strides: tuple[int, ...],
    padding: str
) -> list[range] {
    ranges = [];
    ndims = len(input_shape);
    for d in range(ndims) {
        left_shift = int(kernel_shape[d] / 2);
        right_shift = kernel_shape[d] - left_shift;
        center = output_position[d] * strides[d];
        if padding == 'valid' {
            center += left_shift;
        }
        start = max(0, center - left_shift);
        end = min(input_shape[d], center + right_shift);
        ranges.append(range(start, end));
    }
    return ranges;
}
```

```jac
"""
    Use the bisection method to find the index of a word in a list.
    Precondition: list is sorted
    """
def bisect(slist: list[str], value: str) -> int | None {
    if not all(slist[i] <= slist[i + 1] for i in range(len(slist) - 1)) {
        print('Please supply a sorted list.');
        return None;
    }
    start = 0;
    end = len(slist);
    middle = int(end / 2);
    while slist[middle] != value {
        if slist[middle] > value {
            end = middle;
        } elif slist[middle] < value {
            start = middle;
        }
        middle = start + int((end - start) / 2);
    }
    return middle;
}
```

