```jac
"""Produce matrix indexes in JPEG zig-zag visit order for an n x n matrix."""
def zigzag(n: int) -> list[tuple[int, int]] {
    def move(i: int, j: int) -> tuple[int, int] {
        if j < n - 1 {
            return (max(0, i - 1), j + 1);
        }
        return (i + 1, j);
    }
    mask = [];
    (x, y) = (0, 0);
    for v in range(n * n) {
        mask.append((y, x));
        if (x + y) & 1 {
            (x, y) = move(x, y);
        } else {
            (y, x) = move(y, x);
        }
    }
    return mask;
}
```

