def get_timeout(
    gross_time: int,
    start: int,
    end: int,
    precision: int | float,
    split_range: bool
) -> float {
    if split_range {
        top_num = float(end) / precision;
        bottom_num = float(start) / precision;
        if gross_time % 2 == 0 {
            timeout = top_num - float(gross_time) / precision;
        } else {
