"""Check the cross-turn repetition.

    Calcuate tri-gram repetition.
    """
def check_cross_turn_repetition(context: list[list[str | int]], pred: list[str | int], is_cn: bool = False) -> bool {
    working_context: list[list[str | int]] | list[str] = context;
    working_pred: list[str | int] | str = pred;
    if isinstance(pred[0], str) {
        str_context = [[tok.lower() for tok in utt] for utt in (context as list[list[str]])];
        str_pred = [tok.lower() for tok in (pred as list[str])];
        if is_cn {
            working_context = ["".join(utt) for utt in str_context];
            working_pred = "".join(str_pred);
        } else {
            working_context = str_context;
            working_pred = str_pred;
        }
    }
    pred_tri_grams = set();
    for i in range(len(working_pred) - 2) {
        tri_gram = tuple(working_pred[i:(i + 3)]);
        pred_tri_grams.add(tri_gram);
    }
    for utt in working_context {
        for i in range(len(utt) - 2) {
            tri_gram = tuple(utt[i:(i + 3)]);
            if tri_gram in pred_tri_grams {
                return True;
            }
        }
    }
    return False;
}
