```jac
"""Compute normalisation coefficient for intensity normalisation"""
def std_var_norm(Spectrum: list[float], mean: float) -> float {
    norm = 0.0;
    for val in Spectrum {
        norm = norm + pow(val - mean, 2);
    }
    norm = pow(norm, 0.5) / (len(Spectrum) - 1);
    if norm == 0 {
