```jac
"""
    Returns a copy of text with the replacements applied.

    >>> replace('abc.-.', {'.': '*', '-': '<===>'})
    'abc*<===>*'
    >>> replace('Hola1 que2 ase3', {'Hola': 'Hi', 'que': 'ase', 'ase': None})
    'Hi1 ase2 3'
    """
def replace(text: str, replacements: dict[str, str | None]) -> str {
    if not replacements {
        return text;
    }
    result: list[str] = [];
    start = 0;
    while start < len(text) {
        pattern: list[str] = [];
        for char in text[start:] {
            pattern.append(char);
            try {
                new_value = replacements[''.join(pattern)];
            } except KeyError {
                ;
            } else {
                result.append(new_value or '');
                start += len(pattern);
                break;
            }
        } else {
            result.append(text[start]);
            start += 1;
        }
    }
    return ''.join(result);
}
