def sr(a: list[int]) -> list[tuple[int, int]] {
    r = [];
    i = 0;
    while i < len(a) {
        n = a[i];
        while i + 1 < len(a) and a[i + 1] - a[i] == 1 {
            i += 1;
        }
        if a[i] != n {
            r.append((n, a[i]));
        } else {
            r.append((n, n));
        }
        i += 1;
    }
    return r;
}
